import { computed, inject, resource, Service, signal } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import {
    addGroupUser,
    listMetadata,
    PlaceGroup,
    PlaceGroupUser,
    PlaceUser,
    queryGroups,
    queryGroupUsers,
    removeGroupUser,
    reviveUser,
    updateGroupUser,
} from '@placeos/ts-client';
import { describeError } from '../common/errors';
import { escapeHtml } from '../common/general';
import { ActiveItemService } from '../common/item.service';
import { i18n } from '../common/locale.service';
import { notifyError, notifySuccess } from '../common/notifications';
import { openedTabs } from '../common/opened-tabs';
import { waitForEvent } from '../common/signals';
import {
    GroupBulkAddModalComponent,
    GroupBulkAddModalData,
    GroupBulkAddResult,
} from '../groups/group-bulk-add-modal.component';
import { GroupPermissionsModalComponent } from '../groups/group-permissions-modal.component';
import { openConfirmModal } from '../overlays/confirm-modal.component';

@Service()
export class UsersStateService {
    private _service = inject(ActiveItemService);
    private _dialog = inject(MatDialog);

    /** Set while a bulk add runs */
    private _saving = signal(false);
    private _change = signal(0);

    public readonly loading = computed(
        () =>
            this._saving() ||
            this._metadata_count.isLoading() ||
            this._groups.isLoading(),
    );

    public readonly item = this._service.item;

    // The metadata tab loads its own list, so only the count is needed here
    private readonly _metadata_count = resource({
        params: () => ({
            item: this._service.active_item$(),
            change: this._change(),
        }),
        loader: async ({ params }) => {
            const { item } = params;
            if (!(item instanceof PlaceUser)) return 0;
            return listMetadata(item.id)
                .then((d) => d.length)
                .catch((_err) => 0);
        },
    });

    public readonly counts = computed<{ metadata?: number; groups?: number }>(
        () => ({
            metadata: this._metadata_count.value() || 0,
            groups: this._groups.value()?.total || 0,
        }),
    );

    private readonly _user_id = computed(() => {
        const item = this.item();
        return item instanceof PlaceUser ? item.id : undefined;
    });
    // The group list only loads once its tab is opened. Until then a single
    // row query gives the tab count.
    private readonly _opened_tabs = openedTabs(this._user_id);
    private readonly _load_groups = computed(() =>
        this._opened_tabs().has('groups'),
    );

    private readonly _groups = resource({
        params: () => ({
            item: this.item(),
            change: this._change(),
            full: this._load_groups(),
        }),
        loader: async ({ params }) => {
            const { item, full } = params;
            const empty = { data: [] as PlaceGroupUser[], total: 0 };
            if (!(item instanceof PlaceUser)) return empty;
            const response = await queryGroupUsers({
                user_id: item.id,
                limit: full ? 1000 : 1,
            }).catch((error) => {
                notifyError(
                    i18n('USERS.GROUPS_LOAD_ERROR', {
                        error: describeError(error),
                    }),
                );
                return empty;
            });
            if (!full) return { ...empty, total: response.total };
            return {
                total: response.total,
                data: [...response.data].sort((a, b) =>
                    (a.group?.name || a.group_id).localeCompare(
                        b.group?.name || b.group_id,
                    ),
                ),
            };
        },
    });

    public readonly groups = computed(() => this._groups.value()?.data || []);

    public get active_item(): PlaceUser {
        return this._service.active_item as unknown as PlaceUser;
    }

    public async addGroup(group: PlaceGroup) {
        if (!group?.id) return;
        try {
            await addGroupUser({
                user_id: this.active_item.id,
                group_id: group.id,
            });
        } catch (error) {
            return notifyError(
                i18n('USERS.GROUP_ADD_ERROR', { error: describeError(error) }),
            );
        }
        notifySuccess(i18n('USERS.GROUP_ADD_SUCCESS'));
        this.changed();
    }

    public async bulkAddGroups(existing_groups: PlaceGroupUser[] = []) {
        const result = await waitForEvent(
            this._dialog
                .open<
                    GroupBulkAddModalComponent<PlaceGroup>,
                    GroupBulkAddModalData<PlaceGroup>,
                    GroupBulkAddResult<PlaceGroup>
                >(GroupBulkAddModalComponent<PlaceGroup>, {
                    data: {
                        title: 'USERS.GROUPS_BULK',
                        placeholder: 'GROUPS.SEARCH',
                        empty_message: 'USERS.GROUPS_BULK_EMPTY',
                        query_fn: (query: string) =>
                            queryGroups({
                                q: query,
                                limit: 20,
                                authority_id: this.active_item?.authority_id,
                            } as Record<string, unknown>).then(
                                (response) => response.data,
                            ),
                        exclude: (group: PlaceGroup) => {
                            const authority_id = this.active_item?.authority_id;
                            return (
                                !!existing_groups.find(
                                    (_) => _.group_id === group.id,
                                ) ||
                                (!!authority_id &&
                                    group.authority_id !== authority_id)
                            );
                        },
                    },
                    height: 'auto',
                    width: 'auto',
                    maxHeight: 'calc(100vh - 2em)',
                    maxWidth: 'calc(100vw - 2em)',
                })
                .afterClosed(),
        );
        const groups = result?.items;
        if (!groups?.length) return;
        // Only send permissions when set so the backend default applies
        const permissions = +result.permissions || 0;
        this._saving.set(true);
        const results = await Promise.allSettled(
            groups.map((group) =>
                addGroupUser({
                    user_id: this.active_item.id,
                    group_id: group.id,
                    ...(permissions ? { permissions } : {}),
                }),
            ),
        );
        this._saving.set(false);
        const failed = results.filter((_) => _.status === 'rejected').length;
        if (failed) {
            notifyError(i18n('USERS.GROUPS_BULK_ERROR', { count: failed }));
        }
        const added = results.length - failed;
        if (added) {
            notifySuccess(i18n('USERS.GROUPS_BULK_SUCCESS', { count: added }));
        }
        this.changed();
    }

    public async removeGroup(item: PlaceGroupUser) {
        const details = await openConfirmModal(
            {
                title: i18n('USERS.GROUP_REMOVE'),
                content: i18n('USERS.GROUP_REMOVE_MSG', {
                    name: escapeHtml(item.group?.name || item.group_id),
                }),
                icon: { type: 'icon', content: 'delete' },
            },
            this._dialog,
        );
        if (details.reason !== 'done') return;
        details.loading(i18n('USERS.GROUP_REMOVE_LOADING'));
        try {
            await removeGroupUser(item.user_id, item.group_id);
        } catch (error) {
            details.close();
            return notifyError(
                i18n('USERS.GROUP_REMOVE_ERROR', {
                    error: describeError(error),
                }),
            );
        }
        details.close();
        notifySuccess(i18n('USERS.GROUP_REMOVE_SUCCESS'));
        this.changed();
    }

    public async updateGroup(item: PlaceGroupUser) {
        try {
            await updateGroupUser(item.user_id, item.group_id, {
                permissions: +item.permissions || 0,
            });
        } catch (error) {
            return notifyError(
                i18n('USERS.GROUP_SAVE_ERROR', { error: describeError(error) }),
            );
        }
        notifySuccess(i18n('USERS.GROUP_SAVE_SUCCESS'));
        this.changed();
    }

    public async editGroupPermissions(item: PlaceGroupUser) {
        const result = await waitForEvent(
            this._dialog
                .open(GroupPermissionsModalComponent, {
                    data: {
                        title: 'USERS.GROUP_PERMISSIONS',
                        permissions: item.permissions,
                    },
                })
                .afterClosed(),
        );
        if (!result) return;
        await this.updateGroup({ ...item, permissions: result.permissions });
    }

    /** Restore the selected user after confirmation. */
    public async revive() {
        const item = this.active_item;
        if (!item?.id || !item.deleted || !this._service.canMutate(4)) return;
        const details = await openConfirmModal(
            {
                title: i18n('USERS.REVIVE'),
                content: i18n('USERS.REVIVE_MSG', {
                    name: escapeHtml(item.name),
                }),
                confirm_text: i18n('USERS.REVIVE'),
                icon: { type: 'icon', content: 'restore_from_trash' },
            },
            this._dialog,
        );
        if (details.reason !== 'done') return;
        details.loading(i18n('USERS.REVIVE_LOADING'));
        try {
            await reviveUser(item.id);
            if (this._service.active_item === item) {
                this._service.replaceItem(
                    new PlaceUser({ ...item, deleted: false }),
                );
            }
            this.changed();
            notifySuccess(i18n('USERS.REVIVE_SUCCESS'));
        } catch (error) {
            notifyError(
                i18n('USERS.REVIVE_ERROR', { error: describeError(error) }),
            );
        } finally {
            details.close();
        }
    }

    private changed() {
        this._change.set(Date.now());
    }
}
